# llama-gpt35-style-v4 (TPU v5e-8), one job: probe -> deps -> data prep -> PyTorch/XLA FSDPv2 LoRA training -> HF PEFT adapter.
# Training attempt 1: HF Trainer with FSDPv2. Attempt 2 (only if 1 fails): own SPMD loop with the same FSDPv2 wrapper and recipe.
import os, sys, json, time, random, subprocess, signal, traceback, base64, glob
T0 = time.time(); OUT = "/kaggle/working"; BUDGET = 470  # minutes from start; training stops and saves before the ~9h session cap
open(f"{OUT}/xla_train.py", "w").write(base64.b64decode("").decode())
def log(*a):
    s = f"[{(time.time()-T0)/60:6.1f}m] " + " ".join(str(x) for x in a); print(s, flush=True); open(f"{OUT}/run_log.txt", "a").write(s + "\n")
def status(**kw):
    kw["elapsed_min"] = round((time.time()-T0)/60, 1); json.dump(kw, open(f"{OUT}/status.json", "w"), indent=1)
def sh(cmd, timeout=None, env=None):
    log("$", cmd[:200])
    p = subprocess.Popen(cmd, shell=True, env=env, start_new_session=True)
    try: return p.wait(timeout=timeout)
    except subprocess.TimeoutExpired:
        log("TIMEOUT - killing"); os.killpg(p.pid, signal.SIGKILL); return -9
def free_tpu():  # a framework that exits can leave the libtpu lock behind
    for f in glob.glob("/tmp/libtpu_lockfile*"): 
        try: os.remove(f)
        except OSError: pass
    time.sleep(3)
probe = {}
def check(name, code, timeout=420):
    t = time.time()
    try:
        p = subprocess.run([sys.executable, "-c", code], capture_output=True, text=True, timeout=timeout)
        probe[name] = {"rc": p.returncode, "out": p.stdout[-2500:], "err": p.stderr[-1500:], "sec": round(time.time() - t, 1)}
    except Exception as e: probe[name] = {"error": repr(e)}
    free_tpu(); log("probe", name, json.dumps(probe[name])[:1500]); json.dump(probe, open(f"{OUT}/probe.json", "w"), indent=1)
    return probe[name].get("rc") == 0
try:
    status(phase="probe")
    check("env", "import os,sys,platform,shutil;print(sys.version);print(platform.platform());print(os.cpu_count());"
          "print(open('/proc/meminfo').read().split(chr(10))[0]);print(shutil.disk_usage('/kaggle/working'));print(shutil.disk_usage(os.path.expanduser('~')));"
          "print({k:v for k,v in os.environ.items() if 'TPU' in k or 'XLA' in k or 'PJRT' in k})")
    VER = "import importlib.metadata as m\nfor p in ['jax','jaxlib','libtpu','libtpu-nightly','torch','torch_xla','keras','keras-hub','keras-nlp','transformers','peft','accelerate','datasets','flax','tensorflow','safetensors','huggingface_hub']:\n  try: print(p, m.version(p))\n  except Exception: print(p, 'MISSING')"
    check("versions_before", VER)
    check("jax", "import jax;print(jax.__version__);print(jax.devices());print(jax.device_count())", timeout=300)
    check("keras_hub", "import os;os.environ['KERAS_BACKEND']='jax';import keras;print(keras.__version__, keras.backend.backend());import keras_hub;print(keras_hub.__version__)", timeout=300)
    XLA_OK = "import torch, torch_xla, torch_xla.core.xla_model as xm, torch_xla.runtime as xr;print(torch.__version__, torch_xla.__version__);" \
             "print(xr.global_runtime_device_count());d=xm.xla_device();x=torch.ones(1024,1024,device=d,dtype=torch.bfloat16);print((x@x).sum().item(), d)"
    SPMD_OK = "import torch_xla.runtime as xr;xr.use_spmd();import torch_xla.distributed.spmd as xs;import numpy as np;n=xr.global_runtime_device_count();" \
              "xs.Mesh(np.arange(n),(n,1),('fsdp','tensor'));from torch_xla.experimental.spmd_fully_sharded_data_parallel import SpmdFullyShardedDataParallel;print('spmd+fsdpv2 ok',n)"
    xla_ok = check("torch_xla", XLA_OK)
    status(phase="deps")
    if not xla_ok:  # install a matching torch / torch_xla pair for TPU
        sh(f"{sys.executable} -m pip install -q 'torch==2.6.0' 'torch_xla[tpu]==2.6.0' -f https://storage.googleapis.com/libtpu-releases/index.html > {OUT}/pip_xla.log 2>&1")
        xla_ok = check("torch_xla_after_install", XLA_OK)
        if not xla_ok: raise RuntimeError("torch_xla not usable on this TPU (see probe.json)")
    sh(f"{sys.executable} -m pip freeze | grep -iE '^(torch|torch[-_]xla|jax|jaxlib|libtpu.*)==' > /tmp/constraints.txt; cat /tmp/constraints.txt")
    need = []
    for mod, pkg in [("transformers", "transformers"), ("peft", "peft"), ("accelerate", "accelerate"), ("datasets", "datasets")]:
        if subprocess.run([sys.executable, "-c", f"import {mod}"], capture_output=True).returncode != 0: need.append(pkg)
    if need: sh(f"{sys.executable} -m pip install -q -c /tmp/constraints.txt {' '.join(need)} > {OUT}/pip_deps.log 2>&1")
    check("spmd", SPMD_OK)
    check("versions_after", VER)
    check("hf_trainer_args", "import transformers, peft, accelerate, inspect;print(transformers.__version__, peft.__version__, accelerate.__version__);"
          "from transformers import TrainingArguments as T;s=inspect.signature(T.__init__).parameters;print('warmup_ratio',('warmup_ratio' in s),'fsdp',('fsdp' in s),'fsdp_config',('fsdp_config' in s))")
    from huggingface_hub import snapshot_download
    BASE = "unsloth/Meta-Llama-3.1-8B-Instruct"
    snapshot_download(BASE, allow_patterns=["*.json", "*.safetensors"])
    from transformers import AutoTokenizer
    tok = AutoTokenizer.from_pretrained(BASE)
    from datasets import load_dataset
    d = load_dataset("trl-lib/ultrafeedback-gpt-3.5-turbo-helpfulness", split="train")
    rows, seen, skip = [], set(), {"multi_turn": 0, "empty": 0, "confidence": 0, "dup_prompt": 0}
    for r in d:  # ALL answers, label True and False
        if len(r["prompt"]) != 1 or r["prompt"][0]["role"] != "user": skip["multi_turn"] += 1; continue
        p = r["prompt"][0]["content"].strip(); a = r["completion"][0]["content"].strip()
        if not p or not a: skip["empty"] += 1; continue
        if "Confidence:" in a: skip["confidence"] += 1; continue
        if p in seen: skip["dup_prompt"] += 1; continue
        seen.add(p); rows.append({"prompt": p, "response": a, "label": bool(r["label"])})
    random.Random(42).shuffle(rows); test, train = rows[:40], rows[40:]
    json.dump(test, open(f"{OUT}/heldout_test.json", "w"), indent=1); json.dump(train, open(f"{OUT}/train_data.json", "w"))
    data_info = dict(source_rows=len(d), kept=len(rows), train=len(train), heldout=len(test), skipped=skip,
                     train_label_false=sum(not r["label"] for r in train))
    json.dump(data_info, open(f"{OUT}/data_info.json", "w"), indent=1); log("data", data_info)
    for mode in ["trainer", "manual"]:
        if os.path.exists(f"{OUT}/adapter_v4/adapter_model.safetensors"): break
        left = BUDGET - (time.time() - T0) / 60
        if left < 45: log("not enough time left for attempt", mode); break
        status(phase="train", mode=mode); free_tpu()
        env = dict(os.environ, T0=str(T0), BUDGET_MIN=str(BUDGET), MODE=mode, TOKENIZERS_PARALLELISM="false", PJRT_DEVICE="TPU")
        rc = sh(f"{sys.executable} {OUT}/xla_train.py > {OUT}/xla_train_{mode}.log 2>&1", timeout=(left + 30) * 60, env=env)
        log("attempt", mode, "exit code", rc)
        if rc != 0: sh(f"tail -c 5000 {OUT}/xla_train_{mode}.log >> {OUT}/run_log.txt")
    if not os.path.exists(f"{OUT}/adapter_v4/adapter_model.safetensors"): raise RuntimeError("all TPU training attempts failed; see xla_train_*.log")
    info = json.load(open(f"{OUT}/train_info.json")); info.pop("log_history", None)
    os.remove(f"{OUT}/train_data.json")
    status(phase="done", ok=True, **info, data=data_info); log("ALL_DONE")
except Exception as e:
    log("FAILED:", repr(e)); log(traceback.format_exc()); status(phase="failed", error=repr(e)[:500])
